// HTTP server: serves the web app and a small JSON API over the Store.
// Titles are fetched server-side; data persists to a JSON file (SCN-010).
import express from 'express';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { Store, normalizeUrl, looksLikeUrl } from './store.js';
import { fetchTitle } from './title.js';

const __dirname = dirname(fileURLToPath(import.meta.url));

/**
 * Build the Express app. Dependencies are injectable for testing:
 *  - store: a Store instance
 *  - titleFetcher: async (url) => string
 */
export function createApp({ store, titleFetcher = fetchTitle } = {}) {
  const app = express();
  app.use(express.json());
  app.use(express.static(join(__dirname, 'public')));

  // All bookmarks, newest first. The client does browsing/search/filtering
  // locally over this list (SCN-003, SCN-004, SCN-005, SCN-006).
  app.get('/api/bookmarks', (req, res) => {
    res.json(store.all());
  });

  // Save a link (SCN-001): validate (SCN-008), block duplicates (SCN-008),
  // fetch the real title (SCN-001 / SCN-009), then persist.
  app.post('/api/bookmarks', async (req, res) => {
    const url = normalizeUrl(req.body && req.body.url);
    if (!url) {
      return res.status(400).json({ error: 'empty', message: 'Please provide a web address.' });
    }
    if (!looksLikeUrl(url)) {
      return res.status(400).json({ error: 'invalid', message: 'That does not look like a web address.' });
    }
    const dup = store.findDuplicate(url);
    if (dup) {
      return res.status(409).json({ error: 'duplicate', bookmark: dup });
    }
    const title = await titleFetcher(url);
    const bookmark = store.add({ url, title, tags: req.body && req.body.tags });
    res.status(201).json(bookmark);
  });

  // Edit title/tags (SCN-002), toggle read-later (SCN-005), archive/restore (SCN-006).
  app.patch('/api/bookmarks/:id', (req, res) => {
    const updated = store.update(req.params.id, req.body || {});
    if (!updated) return res.status(404).json({ error: 'not_found' });
    res.json(updated);
  });

  // Permanent delete (SCN-007).
  app.delete('/api/bookmarks/:id', (req, res) => {
    const ok = store.remove(req.params.id);
    if (!ok) return res.status(404).json({ error: 'not_found' });
    res.status(204).end();
  });

  return app;
}

// Direct start (npm start). Not run when imported by tests.
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const dataFile = process.env.DATA_FILE || join(__dirname, 'data', 'bookmarks.json');
  const store = new Store(dataFile);
  const app = createApp({ store });
  const port = Number(process.env.PORT) || 4000;
  app.listen(port, '0.0.0.0', () => {
    console.log(`Bookmarks app listening on http://0.0.0.0:${port} (data: ${dataFile})`);
  });
}

--- STORE ---
// Persistence + domain rules for bookmarks.
// Implements: normalisation, validity check, duplicate detection, CRUD, and
// durable storage. Title retrieval lives in title.js; this module treats a
// resolved title as plain input (SCN-001, SCN-009).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

/** Add an https:// scheme when the user omitted one (SCN-008). */
export function normalizeUrl(raw) {
  const trimmed = String(raw || '').trim();
  if (!trimmed) return '';
  return /^https?:\/\//i.test(trimmed) ? trimmed : 'https://' + trimmed;
}

/** Lightweight validity: a parseable host containing a dot, no whitespace (SCN-008). */
export function looksLikeUrl(url) {
  try {
    const u = new URL(url);
    return (u.protocol === 'http:' || u.protocol === 'https:') &&
      u.hostname.includes('.') && !/\s/.test(u.hostname);
  } catch {
    return false;
  }
}

/**
 * Canonical form for duplicate comparison: host without "www.", path without a
 * trailing slash, plus query; case-insensitive; fragment ignored (SCN-008).
 */
export function canonical(url) {
  try {
    const u = new URL(url);
    const host = u.hostname.replace(/^www\./i, '');
    const path = u.pathname.replace(/\/+$/, '');
    return (host + path + u.search).toLowerCase();
  } catch {
    return String(url || '').toLowerCase();
  }
}

/** Normalise a list of tags: trim, lower-case, drop empties, de-duplicate (SCN-003). */
export function normalizeTags(tags) {
  const out = [];
  const seen = new Set();
  for (const t of Array.isArray(tags) ? tags : []) {
    const tag = String(t).trim().toLowerCase();
    if (tag && !seen.has(tag)) { seen.add(tag); out.push(tag); }
  }
  return out;
}

export class Store {
  constructor(dataFile) {
    this.dataFile = dataFile;
    this.items = this._load();
  }

  _load() {
    try {
      if (existsSync(this.dataFile)) {
        const parsed = JSON.parse(readFileSync(this.dataFile, 'utf8'));
        if (Array.isArray(parsed)) return parsed;
      }
    } catch {
      // Corrupt/unreadable file: start empty rather than crash.
    }
    return [];
  }

  _save() {
    mkdirSync(dirname(this.dataFile), { recursive: true });
    writeFileSync(this.dataFile, JSON.stringify(this.items, null, 2));
  }

  /** All bookmarks, newest first (SCN-001). */
  all() {
    return this.items.slice();
  }

  get(id) {
    return this.items.find((b) => b.id === id) || null;
  }

  /** Find an existing bookmark whose URL matches (canonical) the given URL (SCN-008). */
  findDuplicate(url) {
    const c = canonical(url);
    return this.items.find((b) => canonical(b.url) === c) || null;
  }

  /**
   * Create a bookmark. Caller has already normalised/validated the URL and
   * resolved a title. Returns the created record. Newest goes to the top.
   */
  add({ url, title, tags }) {
    const bookmark = {
      id: randomUUID(),
      url,
      title: title && String(title).trim() ? String(title).trim() : url,
      tags: normalizeTags(tags),
      toRead: false,
      archived: false,
      createdAt: new Date().toISOString(),
    };
    this.items.unshift(bookmark);
    this._save();
    return bookmark;
  }

  /**
   * Update editable fields. title (empty keeps previous — SCN-002), tags,
   * toRead (SCN-005), archived (SCN-006). Returns updated record or null.
   */
  update(id, patch = {}) {
    const b = this.get(id);
    if (!b) return null;
    if (patch.title !== undefined) {
      const t = String(patch.title).trim();
      if (t) b.title = t; // empty title is ignored, previous kept
    }
    if (patch.tags !== undefined) b.tags = normalizeTags(patch.tags);
    if (patch.toRead !== undefined) b.toRead = !!patch.toRead;
    if (patch.archived !== undefined) b.archived = !!patch.archived;
    this._save();
    return b;
  }

  /** Permanently remove a bookmark (SCN-007). Returns true if it existed. */
  remove(id) {
    const i = this.items.findIndex((b) => b.id === id);
    if (i < 0) return false;
    this.items.splice(i, 1);
    this._save();
    return true;
  }
}

