<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>My Bookmarks</title>
  <link rel="stylesheet" href="./styles.css" />
</head>
<body>
  <header class="top">
    <div class="brand"><span class="dot"></span><h1>My Bookmarks</h1></div>
  </header>

  <main>
    <form class="saver" id="saver" autocomplete="off" novalidate>
      <div class="row">
        <input type="url" id="urlInput" placeholder="Paste a link to save…" aria-label="Link to save" />
        <div class="tagfield">
          <input type="text" id="tagInput" placeholder="Add tags (comma-separated)" aria-label="Tags" autocomplete="off" />
          <div class="suggest" id="saveSuggest" role="listbox"></div>
        </div>
        <button type="submit" id="saveBtn">Save link</button>
      </div>
      <div class="hint">Paste a link, add any tags you like, and press Save. A link can carry several tags.</div>
      <div class="savemsg" id="saveMsg" role="status"></div>
    </form>

    <nav class="tabs" id="tabs" aria-label="Views">
      <button data-view="all" class="active" type="button">All <span class="count" id="cntAll">0</span></button>
      <button data-view="toread" type="button">To read <span class="count" id="cntToread">0</span></button>
      <button data-view="archive" type="button">Archived <span class="count" id="cntArchive">0</span></button>
    </nav>

    <div class="searchbar">
      <input type="search" id="searchInput" placeholder="Search your bookmarks…" aria-label="Search bookmarks" />
      <button type="button" id="searchClear" title="Clear search" aria-label="Clear search">×</button>
    </div>

    <div class="tagbar" id="tagbar"></div>

    <h2 class="section-label" id="sectionLabel">Recent</h2>
    <ul class="list" id="list"></ul>
    <div class="empty" id="empty" hidden>
      <div class="big" id="emptyBig">Nothing saved yet</div>
      <div class="sub" id="emptySub">Save your first link above and it will show up here.</div>
    </div>
  </main>

  <div class="overlay" id="delOverlay" hidden>
    <div class="confirm" role="dialog" aria-modal="true" aria-labelledby="delTitle">
      <h2 id="delTitle">Delete this bookmark?</h2>
      <p>This permanently deletes <span class="target" id="delTarget"></span>.</p>
      <p class="warn">This can’t be undone.</p>
      <div class="note">Want to keep it but get it out of the way? Use <strong>Archive</strong> instead — archived links stay saved and can be restored anytime.</div>
      <div class="actions">
        <button class="keep" id="delCancel" type="button">Cancel</button>
        <button class="danger" id="delConfirm" type="button">Delete permanently</button>
      </div>
    </div>
  </div>

  <script src="./app.js" type="module"></script>
</body>
</html>

--- CSS ---
:root {
  --bg: #f6f7f9;
  --card: #ffffff;
  --ink: #1c2430;
  --muted: #6b7684;
  --line: #e3e7ec;
  --accent: #2f6bff;
  --shadow: 0 1px 2px rgba(20,30,50,.06), 0 4px 16px rgba(20,30,50,.05);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.45;
}
.top {
  background: var(--card);
  border-bottom: 1px solid var(--line);
  padding: 14px 20px;
  position: sticky;
  top: 0;
  z-index: 5;
}
.brand { display: flex; align-items: center; gap: 12px; max-width: 820px; margin: 0 auto; }
.top h1 { font-size: 18px; margin: 0; letter-spacing: -.2px; }
.top .dot { width: 22px; height: 22px; border-radius: 7px; background: var(--accent); }
main { max-width: 820px; margin: 0 auto; padding: 20px; }

.saver { background: var(--card); border: 1px solid var(--line); border-radius: 14px; box-shadow: var(--shadow); padding: 16px; margin-bottom: 20px; }
.saver .row { display: flex; gap: 10px; flex-wrap: wrap; }
.saver input[type=url] { flex: 1 1 240px; padding: 12px 14px; font-size: 15px; border: 1px solid var(--line); border-radius: 10px; outline: none; }
.tagfield { position: relative; flex: 1 1 240px; }
.tagfield input { width: 100%; padding: 12px 14px; font-size: 15px; border: 1px solid var(--line); border-radius: 10px; outline: none; }
.saver input:focus, .tagfield input:focus, .searchbar input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(47,107,255,.12); }
.saver button { padding: 12px 18px; font-size: 15px; font-weight: 600; color: #fff; background: var(--accent); border: none; border-radius: 10px; cursor: pointer; white-space: nowrap; }
.saver button:active { transform: translateY(1px); }
.saver .hint { color: var(--muted); font-size: 13px; margin: 10px 2px 0; }
.savemsg { font-size: 13px; margin: 10px 2px 0; padding: 9px 12px; border-radius: 9px; display: none; }
.savemsg.show { display: block; }
.savemsg.err { background: #fdeaea; color: #c0392b; border: 1px solid #f2c2c2; }
.savemsg.info { background: #fff6df; color: #8a6a12; border: 1px solid #f0d68a; }
.savemsg a { color: inherit; font-weight: 600; cursor: pointer; text-decoration: underline; }

.suggest { position: absolute; left: 0; right: 0; top: calc(100% + 4px); background: #fff; border: 1px solid var(--line); border-radius: 10px; box-shadow: var(--shadow); z-index: 9; overflow: hidden; display: none; }
.suggest.open { display: block; }
.suggest .opt { padding: 10px 13px; font-size: 14px; cursor: pointer; display: flex; justify-content: space-between; gap: 12px; }
.suggest .opt:hover, .suggest .opt.hi { background: #eef1f5; }
.suggest .opt .cnt { color: var(--muted); font-size: 12px; }

.tabs { display: flex; gap: 6px; margin-bottom: 16px; border-bottom: 1px solid var(--line); }
.tabs button { border: none; background: transparent; padding: 10px 14px; font-size: 14px; font-weight: 600; color: var(--muted); cursor: pointer; border-bottom: 2px solid transparent; margin-bottom: -1px; display: flex; align-items: center; gap: 7px; }
.tabs button.active { color: var(--accent); border-bottom-color: var(--accent); }
.tabs button .count { font-size: 12px; background: #eef1f5; color: #48566a; border-radius: 999px; padding: 1px 8px; }
.tabs button.active .count { background: #e2ebff; color: var(--accent); }

.searchbar { position: relative; margin-bottom: 16px; }
.searchbar input { width: 100%; padding: 12px 40px 12px 14px; font-size: 15px; border: 1px solid var(--line); border-radius: 10px; outline: none; background: #fff; }
.searchbar #searchClear { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); border: none; background: transparent; font-size: 20px; color: var(--muted); cursor: pointer; line-height: 1; padding: 4px 8px; display: none; }
.searchbar #searchClear.show { display: block; }
mark { background: #fff2ac; color: inherit; border-radius: 3px; padding: 0 1px; }

.tagbar { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; align-items: center; }
.tagbar .lbl { font-size: 13px; color: var(--muted); }
.tag { border: 1px solid var(--line); background: #fff; border-radius: 999px; padding: 6px 12px; font-size: 13px; cursor: pointer; color: var(--ink); }
.tag.active { background: var(--accent); color: #fff; border-color: var(--accent); }
.tag .count { opacity: .7; margin-left: 5px; font-size: 12px; }
