.shimmer { display: inline-block; width: 180px; max-width: 60%; height: 15px; border-radius: 5px; background: linear-gradient(90deg,#eef1f5 25%,#e2e7ee 37%,#eef1f5 63%); background-size: 400% 100%; animation: sh 1.2s ease infinite; vertical-align: middle; }
